/// <summary>Thread-safe notebook for storing research notes.</summary>
sealed class ResearchNotebook
{
    private readonly List<ResearchNote> _notes = [];
    private readonly Lock _lock = new();

    public void Add(string title, string body)
    {
        lock (_lock) { _notes.Add(new ResearchNote(title, body, DateTime.UtcNow)); }
    }

    public IReadOnlyList<ResearchNote> ReadAll()
    {
        lock (_lock) { return [.. _notes]; }
    }
}

