using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tool implementations --------------------------------------------------------

var notebook = new ResearchNotebook();

var searchTool = AIFunctionFactory.Create(
    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    (string query) =>
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍  Searching: \"{query}\"");
        Console.ResetColor();

        // Simulated web search results keyed by broad topic matching.
        var results = WebSearchSimulator.Search(query);
        return results;
    },
    new AIFunctionFactoryOptions { Name = "web_search" });

var saveNoteTool = AIFunctionFactory.Create(
    [Description("Save a research note with a title and body. Use this to record key findings.")]
    (string title, string body) =>
    {
        notebook.Add(title, body);

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝  Note saved: \"{title}\"");
        Console.ResetColor();

        return $"Note \"{title}\" saved successfully.";
    },
    new AIFunctionFactoryOptions { Name = "save_note" });

var readNotesTool = AIFunctionFactory.Create(
    [Description("Read all previously saved research notes. Use before writing the final summary.")]
    () =>
    {
        var notes = notebook.ReadAll();

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📖  Reading {notes.Count} note(s)");
        Console.ResetColor();

        return notes;
    },
    new AIFunctionFactoryOptions { Name = "read_notes" });

// --- Build the AI client pipeline ------------------------------------------------

IChatClient chatClient = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// --- Create the agent ------------------------------------------------------------

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web multiple times to gather diverse information.
        2. Save key findings as notes using the save_note tool.
        3. After gathering enough information, read your notes back.
        4. Write a well-structured summary with sections and citations.
        Be thorough — perform at least 3 searches from different angles.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: [searchTool, saveNoteTool, readNotesTool]);

// --- Run the agent ---------------------------------------------------------------

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the impact of large language models on software engineering";

Console.WriteLine("╔══════════════════════════════════════════════════════════════╗");
Console.WriteLine("║                   🔬  Research Agent                        ║");
Console.WriteLine("╚══════════════════════════════════════════════════════════════╝");
Console.WriteLine();
Console.WriteLine($"  Topic: {topic}");
Console.WriteLine(new string('─', 64));
Console.WriteLine();

var runOptions = new ChatClientAgentRunOptions(
    new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    });

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary:\n\n{topic}",
    options: runOptions);

Console.WriteLine();
Console.WriteLine(new string('─', 64));
Console.WriteLine("  📋  RESEARCH SUMMARY");
Console.WriteLine(new string('─', 64));
Console.WriteLine();

foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine();
Console.WriteLine(new string('─', 64));
Console.WriteLine($"  Notes collected: {notebook.ReadAll().Count}");
Console.WriteLine("  ✅  Research complete.");

